private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    while (bb.hasRemaining()) {
        byte b = bb.get();
        if (b >= 0) {
            sb.append((char) b);
            i++;
        } else {
            // Handle multi-byte UTF-8 characters
            int firstByte = b & 0xFF;
            int numBytes = 0;
            if (firstByte >> 5 == 0b110) { // 2-byte character
                numBytes = 2;
            } else if (firstByte >> 4 == 0b1110) { // 3-byte character
                numBytes = 3;
            } else if (firstByte >> 3 == 0b11110) { // 4-byte character
                numBytes = 4;
            } else {
                // Invalid UTF-8 start byte
                continue;
            }

            // Read the remaining bytes of the character
            char[] charBuffer = new char[1];
            charBuffer[0] = (char) b;
            for (int j = 1; j < numBytes; j++) {
                if (!bb.hasRemaining()) {
                    // Not enough bytes for the character
                    break;
                }
                charBuffer[j % charBuffer.length] = (char) (charBuffer[(j - 1) % charBuffer.length] << 6 | (bb.get() & 0b111111));
            }

            // Append the decoded character
            sb.append(charBuffer[(numBytes - 1) % charBuffer.length]);
            i += numBytes;
        }
    }
    return i;
}
