        char c = (char) ((b & 0x1F) << 6);
        for (int j = 1; j < count; j++) {
            b = bb.get(i + j);
            c |= (b & 0x3F) << (6 - (j * 6));
        }
        sb.append(c);
        return i + count;
    }
