@Override
public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    if (target == null || resultMap == null || resultMap.isEmpty()) {
        return;
    }

    int n = resultMap.size();
    int m = n / 2;

    Set<V> set1 = new HashSet<>();
    Set<V> set2 = new HashSet<>();

    Iterator<Map.Entry<String, V>> iterator = resultMap.entrySet().iterator();
    for (int i = 0; i < m; i++) {
        Map.Entry<String, V> entry = iterator.next();
        set1.add(entry.getValue());
    }
    while (iterator.hasNext()) {
        Map.Entry<String, V> entry = iterator.next();
        set2.add(entry.getValue());
    }

    for (V v1 : set1) {
        for (V v2 : set2) {
            target.addEdge(v1, v2);
        }
    }
}
