protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    long rangeDuration = end - start;
    int segments = (int) (rangeDuration / FETCH_DATA_DURATION);
    if (segments == 0) {
        timeRanges.add(new TimeRange(start, end));
    } else {
        long step = rangeDuration / segments;
        for (int i = 0; i <= segments; i++) {
            long currentStart = start + i * step;
            long currentEnd = start + (i + 1) * step;
            if (i == segments) {
                currentEnd = end;
            }
            timeRanges.add(new TimeRange(currentStart, currentEnd));
        }
    }
    return timeRanges;
}
