private static boolean endsWith(final String str, final String suffix, final boolean ignoreCase) {
    if (str == null) {
        return suffix == null;
    }
    if (suffix == null) {
        return true;
    }
    int strLen = str.length();
    int suffixLen = suffix.length();
    if (strLen < suffixLen) {
        return false;
    }
    int offset = strLen - suffixLen;
    char extstr[] = str.toCharArray();
    char extsuf[] = suffix.toCharArray();
    if (ignoreCase) {
        for (int i = 0; i < suffixLen; i++) {
            if (Character.toLowerCase(extstr[offset + i]) != Character.toLowerCase(extsuf[i])) {
                return false;
            }
        }
    } else {
        for (int i = 0; i < suffixLen; i++) {
            if (extstr[offset + i] != extsuf[i]) {
                return false;
            }
        }
    }
    return true;
}
