private void pop(final String descriptor) {
    if (descriptor.startsWith("(")) {
        int count = 1;
        int i = 1;
        while (i < descriptor.length()) {
            char c = descriptor.charAt(i++);
            if (c == ')') {
                break;
            } else if (c == 'L') {
                while (descriptor.charAt(i++) != ';');
                count++;
            } else if (c == '[') {
                while (descriptor.charAt(i++) == '[');
                char d = descriptor.charAt(i++);
                if (d == 'L') {
                    while (descriptor.charAt(i++) != ';');
                }
                count++;
            } else {
                count++;
            }
        }
        // Pop count number of abstract types from the stack
        while (count > 0) {
            stack.pop();
            count--;
        }
    } else {
        // Pop a single abstract type from the stack
        stack.pop();
    }
}

