private void pop(final String descriptor){
    if (descriptor.charAt(0) == 'L' || descriptor.charAt(0) == '[') {
        Stack<AbstractType> stack = getOutputFrameStack();
        char type = descriptor.charAt(descriptor.length() - 2);
        while (type != ';' && type != ']') {
            stack.pop();
            int nargs = Type.getArgumentsCount(descriptor);
            for (int i = 0; i < nargs; i++) {
                stack.pop();
            }
            type = stack.peek().getType();
        }
    } else {
        Stack<AbstractType> stack = getOutputFrameStack();
        stack.pop();
    }
}
