int function(int desiredCapacity) {
    int capacity = desiredCapacity;
    boolean isPrime = false;

    while (!isPrime) {
        if (capacity < 2) {
            capacity = 2;
        } else {
            isPrime = true;
            for (int i = 2; i <= Math.sqrt(capacity); i++) {
                if (capacity % i == 0) {
                    isPrime = false;
                    break;
                }
            }
        }

        if (capacity >= desiredCapacity && (desiredCapacity >= 1000 ? Math.abs((double) (capacity - desiredCapacity) / desiredCapacity) <= 0.11 : true)) {
            break;
        }

        capacity++;
    }

    return capacity;
}
