    int function(int desiredCapacity) {
        if (desiredCapacity < 2) {
            return 2;
        }
        int candidate = (desiredCapacity % 2 == 0) ? desiredCapacity + 1 : desiredCapacity;
        while (!isPrime(candidate)) {
            candidate += 2;
        }
        int maxAllowedDifference = (desiredCapacity >= 1000) ? Math.round(0.11f * desiredCapacity) : Integer.MAX_VALUE;
        if (Math.abs(candidate - desiredCapacity) > maxAllowedDifference) {
            candidate = desiredCapacity + maxAllowedDifference;
            while (!isPrime(candidate)) {
                candidate += 2;
            }
        }
        return candidate;
    }

    private boolean isPrime(int number) {
        if (number <= 1) {
            return false;
        }
        if (number == 2) {
            return true;
        }
        if (number % 2 == 0) {
            return false;
        }
        for (int i = 3; i <= Math.sqrt(number); i += 2) {
            if (number % i == 0) {
                return false;
            }
        }
        return true;
    }
