                case '"':
                    sb.append('"');
                    break;
                case '\'':
                    sb.append('\'');
                    break;
                case '\\':
                    sb.append('\\');
                    break;
                default:
                    sb.append('\\').append(c);
            }
            lastWasEscape = false;
        } else {
            if (c == '\\') {
                lastWasEscape = true;
            } else {
                sb.append(c);
