protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    List<E> edges = new ArrayList<>(tour);
    V start = null;
    for (E edge : edges) {
        V v1 = graph.getEdgeSource(edge);
        V v2 = graph.getEdgeTarget(edge);
        if (start == null) {
            start = v1;
        }
        if (start.equals(v2)) {
            start = v1;
        }
    }
    List<V> vertexList = new ArrayList<>();
    V current = start;
    while (true) {
        vertexList.add(current);
        E currentEdge = null;
        for (E edge : edges) {
            if (graph.getEdgeSource(edge).equals(current)) {
                currentEdge = edge;
                break;
            }
        }
        if (currentEdge == null) {
            break;
        }
        current = graph.getEdgeTarget(currentEdge);
    }
    return graph.getPath(vertexList.get(0), vertexList.get(vertexList.size() - 1), edges, false);
}
