protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    List<E> edgeList = new ArrayList<>(tour);
    V start = edgeList.get(0).getEndpoint(0);
    V current = start;
    List<V> vertexList = new ArrayList<>();
    vertexList.add(current);
    edgeList.add(edgeList.remove(0)); // Move the first edge to the end to close the tour
    for (E e : edgeList) {
        V next = e.getOtherEndpoint(current);
        vertexList.add(next);
        current = next;
    }
    return graph.createPath(vertexList);
}
