public class ArrayUtils {
    public static final <V> void reverse(V[] arr, int from, int to) {
        while (from < to) {
            V temp = arr[from];
            arr[from] = arr[to];
            arr[to] = temp;
            from++;
            to--;
        }
    }

    public static void main(String[] args) {
        Integer[] array = {1, 2, 3, 4, 5};
        reverse(array, 1, 3);
        System.out.println(Arrays.toString(array)); // Output: [1, 4, 3, 2, 5]
