                    Set<Integer> separator = new HashSet<>(graph.adj(u));
                    separator.retainAll(graph.adj(v));
                    if (separator.size() > 1) {
                        localSeparatorList.add(new Pair<>(new ArrayList<>(separator), e));
                    }
                }
            }
        }
        globalSeparatorList.add(new Pair<>(localSeparatorList, e));
    }
    return globalSeparatorList;
}
